from z3 import *

# Create a Z3 solver
s = Solver()

# Variables
E = [[Bool(f"E_{i}_{j}") if i < j else Bool(f"E_{j}_{i}") if i > j else False for j in range(12)] for i in range(12)]
C = [Int(f"C_{i}") for i in range(12)]

# Constraints
# Colors are 0, 1, 2
for i in range(12):
    s.add(C[i] >= 0, C[i] <= 2)

# Edges imply different colors
for i in range(12):
    for j in range(i + 1, 12):
        s.add(Implies(E[i][j], C[i] != C[j]))

# Minimum degree >= 3
for i in range(12):
    s.add(Sum([If(E[i][j], 1, 0) for j in range(12) if i != j]) >= 3)

# Known edges
known_edges = [(1,2), (0,2), (1,4), (2,9), (2,7)]
for u, v in known_edges:
    if u > v:
        u, v = v, u
    s.add(E[u][v] == True)

# Solve
if s.check() == sat:
    m = s.model()
    edges = []
    for i in range(12):
        for j in range(i + 1, 12):
            if is_true(m[E[i][j]]):
                edges.append((i, j))
    print("SAT")
    print(edges)
else:
    print("UNSAT")
